// Built for one generated fixture. Pinned is generated by qualify-bounded-finder.py.
// The caller cannot supply a remote name, worker, operation arguments, or credentials.
import CryptoKit
import Foundation
import Security

struct Saved: Decodable {
    let endpoint: String
    let bucket: String
    let prefix: String
    let accessKey: String
    let secretKey: String
}

struct Failure: Error {}
func require(_ condition: Bool) throws { if !condition { throw Failure() } }
func digest(_ bytes: Data) -> String {
    SHA256.hash(data: bytes).map { String(format: "%02x", $0) }.joined()
}

@main
enum FixtureRunner {
    static func main() {
        do { try run() }
        catch { FileHandle.standardError.write(Data("qualification precondition failed\n".utf8)); exit(1) }
    }

    // The two supported queries return only small marker data or its metadata.
    static func capture(_ binary: URL, _ env: [String:String], _ arguments: [String], maximum: Int = 65535) throws -> Data {
        let task = Process()
        task.executableURL = binary
        task.environment = env
        task.arguments = arguments + ["--config", "/dev/null"]
        task.standardError = FileHandle.nullDevice
        let output = Pipe()
        task.standardOutput = output
        try task.run()
        let data = output.fileHandleForReading.readDataToEndOfFile()
        task.waitUntilExit()
        try require(task.terminationStatus == 0 && data.count <= maximum)
        return data
    }

    static func validAppleDouble(_ d: Data) -> Bool {
        guard d.count >= 26 else { return false }
        func integer(_ position: Int, _ length: Int) -> Int {
            d[position..<position+length].reduce(0) { ($0 << 8) | Int($1) }
        }
        let count = integer(24,2)
        let first = 26 + count * 12
        guard integer(0,4) == 0x51607, integer(4,4) == 0x20000, (1...256).contains(count), first <= d.count else { return false }
        var ranges: [Range<Int>] = []
        var tags: Set<Int> = []
        for i in 0..<count {
            let record = 26+i*12
            let tag = integer(record,4), start = integer(record+4,4), length = integer(record+8,4)
            guard start >= first, start+length <= d.count, tags.insert(tag).inserted else { return false }
            let range = start..<start+length
            guard ranges.allSatisfy({ !$0.overlaps(range) }) else { return false }
            ranges.append(range)
        }
        return true
    }

    static func run() throws {
        try require(CommandLine.arguments.count == 2)
        let task = CommandLine.arguments[1]
        try require(["serve", "serve-held", "read", "read-native-record", "read-native-large", "files", "stages", "clean-payload", "clean-marker", "clean-finder-companions", "clean-native-managed", "inspect-stages", "clean-proven-orphans"].contains(task))
        let binary = URL(fileURLWithPath: Pinned.worker)
        try require(digest(try Data(contentsOf: binary, options: .mappedIfSafe)) == Pinned.sha)
        // No prompts, migrations, writes, or broad Keychain queries.
        try require(SecKeychainSetUserInteractionAllowed(false) == errSecSuccess)
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword, kSecAttrService as String: "local.bucketdrive.r2.v2",
            kSecAttrAccount as String: "primary", kSecMatchLimit as String: kSecMatchLimitOne,
            kSecReturnData as String: true
        ]
        var result: CFTypeRef?
        try require(SecItemCopyMatching(query as CFDictionary, &result) == errSecSuccess)
        guard let bytes = result as? Data else { throw Failure() }
        let config = try JSONDecoder().decode(Saved.self, from: bytes)
        guard let endpoint = URLComponents(string: config.endpoint) else { throw Failure() }
        try require(endpoint.scheme == "https" && endpoint.host?.hasSuffix(".r2.cloudflarestorage.com") == true &&
                    endpoint.user == nil && endpoint.password == nil && endpoint.port == nil &&
                    endpoint.query == nil && endpoint.fragment == nil && ["", "/"].contains(endpoint.path))
        try require(config.bucket.range(of: "^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$", options: .regularExpression) != nil)
        let prefix = "clouddrive-qualification-" + Pinned.id
        let binding = digest(Data((config.endpoint + "/" + config.bucket + "/" + prefix).utf8))
        let stage = ".clouddrive-spill-" + binding
        let ownerRoot = config.prefix.split(separator: "/").first.map(String.init)
        try require(ownerRoot != nil && ownerRoot != prefix && ownerRoot != stage)
        let remote = "bucket:" + config.bucket + "/"
        let object = remote + prefix + "/finder-payload.bin"
        let child = Process()
        child.executableURL = binary
        var env = ["PATH": "/usr/bin:/bin:/usr/sbin:/sbin", "HOME": Pinned.root,
            "TMPDIR": Pinned.root + "/cache-volume/temp", "RCLONE_CONFIG_BUCKET_TYPE": "s3",
            "RCLONE_CONFIG_BUCKET_PROVIDER": "Cloudflare", "RCLONE_CONFIG_BUCKET_REGION": "auto",
            "RCLONE_CONFIG_BUCKET_NO_CHECK_BUCKET": "true", "RCLONE_CONFIG_BUCKET_ENDPOINT": config.endpoint,
            "RCLONE_CONFIG_BUCKET_ACCESS_KEY_ID": config.accessKey, "RCLONE_CONFIG_BUCKET_SECRET_ACCESS_KEY": config.secretKey]
        var args: [String]
        switch task {
        case "serve", "serve-held":
            guard let token = readLine(), token.range(of: "^[0-9a-f]{64}$", options: .regularExpression) != nil else { throw Failure() }
            env["RCLONE_RC_USER"] = "fixture"
            env["RCLONE_RC_PASS"] = token
            args = ["serve", "nfs", remote + prefix, "--addr", "127.0.0.1:" + Pinned.nfs,
                "--rc", "--rc-addr", "127.0.0.1:" + Pinned.rc, "--vfs-cache-mode", "full",
                "--cache-dir", Pinned.root + "/cache-volume/cache", "--temp-dir", Pinned.root + "/cache-volume/temp",
                "--vfs-write-back", task == "serve-held" ? "1h" : "1s", "--vfs-cache-max-age", "1s", "--vfs-cache-poll-interval", "1s",
                "--vfs-spill-window", "32Mi", "--vfs-spill-prefix", stage,
                "--vfs-move-journal", Pinned.root + "/cache-volume/moves", "--vfs-move-binding", binding,
                "--buffer-size", "4M", "--vfs-read-chunk-size", "8M", "--vfs-read-chunk-size-limit", "32M",
                "--dir-cache-time", "30s", "--poll-interval", "0", "--transfers", "2"]
        case "read": args = ["cat", object]
        case "read-native-record":
            let selection = URL(fileURLWithPath: Pinned.root).appendingPathComponent("managed-read-selector")
            let key = try String(contentsOf: selection, encoding: .utf8)
            try require(key == "HEAD" || key.range(of: "^(commits|metadata)/[a-f0-9]{64}$", options: .regularExpression) != nil)
            args = ["cat", remote + prefix + "/.clouddrive/v1/" + key, "--count", "262145"]
        case "read-native-large":
            let key = try String(contentsOf: URL(fileURLWithPath: Pinned.root).appendingPathComponent("native-read-key"), encoding: .utf8)
            let base = prefix + "/.clouddrive/v1/content/"
            try require(key.hasPrefix(base) && String(key.dropFirst(base.count)).range(of: "^[0-9A-Fa-f/-]{30,160}$", options: .regularExpression) != nil)
            args = ["cat", remote + key, "--count", "234881025"]
        case "files": args = ["lsjson", remote + prefix, "--recursive", "--no-modtime", "--no-mimetype"]
        case "stages": args = ["lsjson", remote + stage, "--recursive", "--no-modtime", "--no-mimetype"]
        case "clean-payload": args = ["deletefile", object]
        case "clean-native-managed":
            // The outer harness enables this mode only after the signed qualification
            // verified a complete R2 read, a normal unmount and a safe owner stop.
            try require(Pinned.verifiedSourceSHA.range(of: "^[0-9a-f]{64}$", options: .regularExpression) != nil)
            let listing = try capture(binary, env, ["lsjson", remote + prefix, "--recursive", "--metadata", "--no-modtime", "--no-mimetype"], maximum: 32 * 1024 * 1024)
            guard let entries = try JSONSerialization.jsonObject(with: listing) as? [[String:Any]] else { throw Failure() }
            var keys = Set<String>()
            for entry in entries where entry["IsDir"] as? Bool == false {
                guard let key = entry["Path"] as? String, let size = entry["Size"] as? Int, size >= 0,
                      let metadata = entry["Metadata"] as? [String:String],
                      let operation = metadata["clouddrive-operation-id"], UUID(uuidString: operation) != nil else { throw Failure() }
                let path = key.components(separatedBy: "/")
                try require(path.count >= 3 && path[0] == ".clouddrive" && path[1] == "v1")
                switch path[2] {
                case "HEAD":
                    try require(path.count == 3 && size <= 1_048_576)
                case "commits", "metadata":
                    try require(path.count == 4 && path[3].range(of: "^[a-f0-9]{64}$", options: .regularExpression) != nil)
                case "content":
                    try require(path.dropFirst(3).joined(separator: "/").range(of: "^[0-9A-Fa-f/-]{30,160}$", options: .regularExpression) != nil)
                default: throw Failure()
                }
                try require(keys.insert(key).inserted)
            }
            try require(keys.contains(".clouddrive/v1/HEAD"))
            // Both supported manifest versions use the same v1 key layout.
            // Validate the tip against its immutable commit before cleanup.
            let base = remote + prefix + "/.clouddrive/v1/"
            let headData = try capture(binary, env, ["cat", base + "HEAD", "--count", "4097"], maximum: 4096)
            guard let head = try JSONSerialization.jsonObject(with: headData) as? [String: Any],
                  let version = head["version"] as? Int, (1...2).contains(version),
                  let volume = head["volumeID"] as? String, UUID(uuidString: volume) != nil,
                  let commit = head["commitID"] as? String,
                  keys.contains(".clouddrive/v1/commits/" + commit) else { throw Failure() }
            let content = try capture(binary, env, ["cat", base + "commits/" + commit, "--count", "262145"], maximum: 262144)
            guard digest(content) == commit,
                  let decoded = try JSONSerialization.jsonObject(with: content) as? [String: Any],
                  decoded["version"] as? Int == version, decoded["volumeID"] as? String == volume else { throw Failure() }
            let manifest = URL(fileURLWithPath: Pinned.root).appendingPathComponent("managed-cleanup.txt")
            try Data((keys.sorted().joined(separator: "\n") + "\n").utf8).write(to: manifest, options: .withoutOverwriting)
            args = ["delete", remote + prefix, "--files-from-raw", manifest.path, "--max-delete", String(keys.count)]
        case "clean-proven-orphans":
            // This mode is available only on a separately built cleanup launcher after
            // a completed provider GET, normal unmount, worker exit, and image detach.
            try require(!Pinned.verifiedSourceSHA.isEmpty)
            let source = URL(fileURLWithPath:Pinned.root).appendingPathComponent("finder-payload.bin")
            let localBytes = try Data(contentsOf:source, options:.mappedIfSafe)
            try require(digest(localBytes) == Pinned.verifiedSourceSHA)
            let page = 4*1024*1024
            var hashes = Set<String>()
            for start in stride(from:0,to:localBytes.count,by:page) {
                hashes.insert(digest(localBytes.subdata(in:start..<min(start+page,localBytes.count))))
            }
            let owner = try capture(binary,env,["cat",remote+stage+"/"+Pinned.marker,"--count","4097"])
            try require(owner == Data(("CloudDrive spill v1\n"+config.bucket+"/"+prefix+"\n").utf8))
            let data = try capture(binary,env,["lsjson",remote+stage,"--recursive","--metadata","--no-modtime","--no-mimetype"])
            guard let objects = try JSONSerialization.jsonObject(with:data) as? [[String:Any]] else { throw Failure() }
            var verified = [String]()
            var markers = 0
            for item in objects where item["IsDir"] as? Bool == false {
                guard let path = item["Path"] as? String, let size = item["Size"] as? Int,
                      let metadata = item["Metadata"] as? [String:String],
                      metadata["clouddrive-spill-id"] == stage+"/"+path else { throw Failure() }
                if path == Pinned.marker { markers += 1; continue }
                let parts = path.split(separator:"/")
                try require(parts.count == 2 && UUID(uuidString:String(parts[0])) != nil && hashes.contains(String(parts[1])) && size > 0 && size <= page)
                let uri = remote+stage+"/"+path
                let bytes = try capture(binary,env,["cat",uri,"--count",String(page+1)],maximum:page)
                try require(bytes.count == size && digest(bytes)==String(parts[1]))
                verified.append(uri)
            }
            try require(markers == 1)
            for uri in verified { _ = try capture(binary,env,["deletefile",uri]) }
            return
        case "inspect-stages":
            let listing = try capture(binary, env, ["lsjson", remote + stage, "--recursive", "--metadata", "--no-modtime", "--no-mimetype"])
            guard let objects = try JSONSerialization.jsonObject(with: listing) as? [[String:Any]] else { throw Failure() }
            var generations = Set<String>()
            var total = 0, identified = 0, markers = 0
            for item in objects where item["IsDir"] as? Bool == false {
                guard let key = item["Path"] as? String else { throw Failure() }
                if key == Pinned.marker { markers += 1; continue }
                let fields = key.split(separator: "/")
                try require(fields.count == 2 && UUID(uuidString: String(fields[0])) != nil)
                generations.insert(String(fields[0]))
                if let metadata = item["Metadata"] as? [String:String], metadata["clouddrive-spill-id"] == stage+"/"+key {
                    identified += 1
                }
                total += 1
            }
            let summary = ["generations":generations.count,"chunks":total,"identityMatched":identified,"markers":markers]
            FileHandle.standardOutput.write(try JSONSerialization.data(withJSONObject: summary))
            return
        case "clean-finder-companions":
            let listing = try capture(binary, env, ["lsjson", remote + prefix, "--recursive", "--no-modtime", "--no-mimetype"])
            guard let objects = try JSONSerialization.jsonObject(with: listing) as? [[String:Any]] else { throw Failure() }
            var verified: [String] = []
            for item in objects {
                guard item["IsDir"] as? Bool == false, let key = item["Path"] as? String,
                      [".DS_Store", "._.DS_Store", "._finder-payload.bin"].contains(key),
                      let size = item["Size"] as? Int, size > 7 && size < 65536 else { throw Failure() }
                let uri = remote + prefix + "/" + key
                let data = try capture(binary, env, ["cat", uri, "--count", "65535"])
                try require(data.count == size)
                if key == ".DS_Store" {
                    try require(data.prefix(8) == Data([0,0,0,1,0x42,0x75,0x64,0x31]))
                } else {
                    try require(validAppleDouble(data))
                }
                verified.append(uri)
            }
            for uri in verified { _ = try capture(binary, env, ["deletefile", uri]) }
            return
        case "clean-marker":
            let key = stage + "/" + Pinned.marker
            let object = remote + key
            let marker = try capture(binary, env, ["cat", object, "--count", "4097"])
            try require(marker == Data(("CloudDrive spill v1\n" + config.bucket + "/" + prefix + "\n").utf8))
            let metadataBytes = try capture(binary, env, ["lsjson", object, "--stat", "--metadata"])
            guard let details = try JSONSerialization.jsonObject(with: metadataBytes) as? [String: Any],
                  let metadata = details["Metadata"] as? [String: String] else { throw Failure() }
            try require(metadata["clouddrive-spill-id"] == key)
            args = ["deletefile", object]
        default: throw Failure()
        }
        child.environment = env
        child.arguments = args + ["--config", "/dev/null"]
        let diagnostics = Pipe()
        let serving = task == "serve" || task == "serve-held"
        child.standardError = serving ? diagnostics : FileHandle.nullDevice
        try child.run()
        if serving {
            let classes = [("notimplemented", "provider-not-implemented"), ("not implemented", "provider-not-implemented"),
                           ("501", "provider-501"), ("retained private", "spill-cleanup-retained"),
                           ("verification", "verification"), ("checksum mismatch", "checksum-mismatch"),
                           ("no space left", "no-space"), ("failed to", "worker-error")]
            var carry = ""
            while true {
                let bytes = diagnostics.fileHandleForReading.availableData
                if bytes.isEmpty { break }
                let lines = (carry + String(decoding: bytes, as: UTF8.self)).lowercased().components(separatedBy:"\n")
                carry = String((lines.last ?? "").suffix(4096))
                for line in lines.dropLast() {
                    for (pattern, label) in classes where line.contains(pattern) {
                        FileHandle.standardError.write(Data((label + "\n").utf8))
                    }
                }
            }
        }
        child.waitUntilExit()
        exit(child.terminationStatus)
    }
}
